{
  "name": "wsl-notify",
  "version": "1.0.5",
  "description": "Windows toast notifications for OpenCode — permission, question, session completion and error events. Zero dependencies, one entrypoint for OpenCode V1 and V2, works from WSL (powershell.exe interop) and native Windows.",
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "main": "index.js",
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notification",
    "notifications",
    "toast",
    "windows",
    "wsl",
    "powershell"
  ],
  "license": "MIT",
  "author": "Alexey Shirshov",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AlexeyShirshov/skills.git",
    "directory": "opencode/plugins/wsl-notify"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "test": "node test/smoke.mjs"
  }
}
